#include <iostream>
#include <string>
using namespace std;

class Cat {
private:
    string name;
    int fish;

public:
    Cat(string n, int f) : name(n), fish(f) {}

    string getName() const {
        return name;
    }

    int getFish() const {
        return fish;
    }

    void setFish(int f) {
        if (f < 0) {
            cout << "不许倒扣喵" << endl;
            return;
        }
        fish = f;
    }
};

int main() {
    int a = 0;
    int b = 0;
    cin >> a >> b;

    Cat c1("{name}", a);
    c1.setFish(b);
    cout << c1.getName() << " 有 " << c1.getFish() << " 条" << endl;
    return 0;
}
